def squash(s: str) -> str:
    n = len(s)
    out: list[str] = []
    i = 0
    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1
        count = j - i
        esc = "\\" + c if (c == "\\" or "0" <= c <= "9") else c
        if count >= 3:
            out.append(f"{count}{esc}")
        else:
            out.append(esc * count)
        i = j
    return "".join(out)
